const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for northern Lake Eyre
  const lakeEyreNorth = ee.Geometry.Rectangle([137.0, -28.0, 138.5, -29.0]);

  // 2. Date ranges with buffer
  const date1Start = '2025-06-15';
  const date1End = '2025-06-25';
  const date2Start = '2025-09-10';
  const date2End = '2025-09-20';

  // Function to get water extent
  function getWaterExtent(startDate, endDate, geometry) {
    // Try Sentinel-2 first (higher resolution for water)
    let s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    let collectionSize = s2.size().getInfo();

    // Fallback to Landsat if no Sentinel-2 images
    if (collectionSize === 0) {
      let ls = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterDate(startDate, endDate)
        .filterBounds(geometry)
        .filter(ee.Filter.lt('CLOUD_COVER', 30));

      collectionSize = ls.size().getInfo();

      if (collectionSize === 0) {
        return {count: null, images: 0, source: 'None'};
      }

      // Use Landsat - MNDWI for water detection
      let image = ls.median();
      let mndwi = image.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI');
      let waterMask = mndwi.gt(0);
      let count = waterMask.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: 1000,
        maxPixels: 1e9
      }).get('MNDWI').getInfo();

      return {count: count, images: collectionSize, source: 'Landsat9'};
    }

    // Use Sentinel-2 - MNDWI (Green - SWIR)
    let image = s2.median();
    let mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
    let waterMask = mndwi.gt(0);
    let count = waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    }).get('MNDWI').getInfo();

    return {count: count, images: collectionSize, source: 'Sentinel2'};
  }

  // 3. Get water extents for both periods
  const water1 = getWaterExtent(date1Start, date1End, lakeEyreNorth);
  const water2 = getWaterExtent(date2Start, date2End, lakeEyreNorth);

  // 4. Print results
  console.log(`June 2025: ${water1.images} images (${water1.source}), Water pixels: ${water1.count}`);
  console.log(`Sept 2025: ${water2.images} images (${water2.source}), Water pixels: ${water2.count}`);

  // 5. Determine answer
  if (water1.images === 0 || water2.images === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  if (water1.count === 0 || water2.count === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (water1.count === null || water2.count === null || 
      isNaN(water1.count) || isNaN(water2.count)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Check if water extent increased
  if (water2.count > water1.count) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
